{
  "hypotheses": [
    {
      "id": "H1",
      "mechanism": "The controller's gait frequency parameter (freq) is mismatched to the shorter leg length, causing excessively rapid steps (step_freq_hz=5.2 vs pendulum 0.714 Hz) and forward falls.",
      "evidence": [
        "baseline.controller_freq_ratio",
        "baseline.step_freq_hz",
        "baseline.pendulum_freq_hz",
        "baseline.forward_fall_frac",
        "baseline.pitch_drift_radps"
      ],
      "competing": [
        "The high step frequency may be a consequence of forward falling (the creature steps faster to catch up) rather than a cause; the root cause could be excessive forward pitch drift from posture or feedback parameters."
      ]
    },
    {
      "id": "H2",
      "mechanism": "Foot placement feedback gains (fp_kd, fp_kv) are zero initially, so the controller cannot adjust foot placement to capture the torso, resulting in large negative capture margins and forward falls.",
      "evidence": [
        "baseline.capture_margin_over_leg_mean",
        "baseline.capture_margin_over_leg_min",
        "baseline.touchdown_foot_ahead_over_leg_mean",
        "baseline.touchdown_foot_ahead_trend"
      ],
      "competing": [
        "The negative capture margin could stem from excessive forward torso lean (pitch_mean_rad=0.1393, pitch_at_end_rad=0.916) caused by incorrect pitch_ref or hip_bias, not lack of placement feedback."
      ]
    },
    {
      "id": "H3",
      "mechanism": "Body morphology (shorter legs, smaller feet, heavier torso, lower torque authority) differs substantially from the reference body the controller was tuned for, making the transferred controller fundamentally incompatible without body changes.",
      "evidence": [
        "creature.features.L",
        "creature.reference.features.L",
        "creature.features.foot_to_leg",
        "creature.reference.features.foot_to_leg",
        "creature.features.torso_frac",
        "creature.reference.features.torso_frac",
        "creature.features.tau_ratio",
        "creature.reference.features.tau_ratio"
      ],
      "competing": [
        "The controller might adapt to the current body if given appropriate control subspace optimization (timing, posture, feedback, stride) without changing body parameters."
      ]
    }
  ],
  "probes": [
    {
      "probe_id": "opt_timing",
      "hypothesis": "H1",
      "expect": "improves"
    },
    {
      "probe_id": "opt_placement",
      "hypothesis": "H2",
      "expect": "improves"
    },
    {
      "probe_id": "opt_body",
      "hypothesis": "H3",
      "expect": "improves"
    }
  ]
}

